INSERT INTO `feedback_tbl` (`fd_id`, `fd_email`, `fd_star`, `fd_emoji`, `fd_description`, `fd_created_at`) VALUES
(9, 'hiral@gmail.com', '4', '😃', 'Excellent user experience. Upload a photo, select a mood, and instantly receive high-quality captions, hashtags, and song suggestions. Simple, smart, and professional.', '2025-11-17'),
(10, 'suhana@gmail.com', '5', '😃', 'A brilliantly designed tool that transforms a single photo into perfect captions, powerful hashtags and curated song picks. Effortless and impressive.', '2025-11-17'),
(11, 'ayan@gmail.com', '3', '😃', 'The mood-based suggestions are remarkably accurate—captions, hashtags, and songs that feel tailor-made. A must-have for standout social posts.', '2025-11-17'),
(12, 'shyama@gmail.com', '5', '😃', 'Captures the vibe perfectly every time. The combination of caption, hashtag, and song suggestions makes content creation feel easy and inspiring.', '2025-11-17'),
(13, 'heer@gmail.com', '5', '😃', 'A next-level creative assistant—delivering aesthetically aligned captions, optimized hashtags, and mood-fitting songs with impressive accuracy.', '2025-11-17'),
(14, 'harsh@gmail.com', '5', '😃', 'Fast, stylish, and surprisingly precise. This tool turns your photo’s mood into the perfect caption, hashtag set, and song recommendation instantly.', '2025-11-17');

